export function getNormalizedVereinsId(vereinsId?: string): string {
  const norm = (vereinsId || 'sv-neuhausen').toLowerCase().trim().replace(/\s/g, '');
  const INVALID_IDS = [
    '', 'api', 'admin', 'superadmin', 'reservation', 'reports', 'tournaments',
    'ranking', 'help', 'guests', 'adminsettings', 'undefined', 'null',
    'public', 'assets', 'static', 'vite', 'system', 'super-admin'
  ];
  if (!norm || INVALID_IDS.includes(norm)) {
    return 'sv-neuhausen';
  }
  return norm;
}

export function deepCleanUndefined(obj: any): any {
  if (obj === undefined) {
    return null;
  }
  if (obj === null) {
    return null;
  }
  if (Array.isArray(obj)) {
    return obj.map(item => deepCleanUndefined(item));
  }
  if (typeof obj === 'object') {
    if (obj instanceof Date) {
      return obj;
    }
    const cleanObj: any = {};
    for (const [key, value] of Object.entries(obj)) {
      if (value !== undefined) {
        cleanObj[key] = deepCleanUndefined(value);
      }
    }
    return cleanObj;
  }
  return obj;
}

export async function performClubMigration(oldId: string, newId: string) {
  console.log(`Starting migration from ${oldId} to ${newId}...`);
  try {
    const oldClubRef = doc(db, 'vereine', oldId);
    const oldClubSnap = await getDoc(oldClubRef);
    if (oldClubSnap.exists()) {
      const clubData = oldClubSnap.data();
      await setDoc(doc(db, 'vereine', newId), {
        ...clubData,
        vereinsId: newId,
        clubName: clubData.clubName || clubData.vereinsName || newId
      }, { merge: true });
    }

    // Migrate flat users associated with the old tenant
    try {
      const usersQ = query(collection(db, 'users'), where('tenantId', '==', oldId));
      const usersSnap = await getDocs(usersQ);
      for (const d of usersSnap.docs) {
        const userData = d.data();
        await setDoc(doc(db, 'users', d.id), {
          ...userData,
          tenantId: newId,
          vereinsId: newId
        }, { merge: true });
      }
    } catch (e) {
      console.error(`Error migrating users of club ${oldId} to ${newId}:`, e);
    }

    const subcollections = ['mitglieder', 'bookings', 'tournaments', 'backups', 'state', 'arbeitseinsaetze'];
    for (const sub of subcollections) {
      const oldColRef = collection(db, 'vereine', oldId, sub);
      const docsSnap = await getDocs(oldColRef);
      for (const d of docsSnap.docs) {
        const docData = d.data();
        let newDocData = { ...docData };
        if (sub === 'mitglieder') {
          newDocData.vereinsId = newId;
        }
        await setDoc(doc(db, 'vereine', newId, sub, d.id), newDocData, { merge: true });
      }
    }
    
    await deleteDoc(oldClubRef);
    for (const sub of subcollections) {
      const oldColRef = collection(db, 'vereine', oldId, sub);
      const docsSnap = await getDocs(oldColRef);
      for (const d of docsSnap.docs) {
        await deleteDoc(doc(db, 'vereine', oldId, sub, d.id));
      }
    }
    console.log(`Successfully completed migration from ${oldId} to ${newId}.`);
  } catch (err) {
    console.error(`Error during club migration from ${oldId} to ${newId}:`, err);
  }
}

