export async function saveBooking(vereinsId: string, booking: Booking) {
  const normalizedId = getNormalizedVereinsId(vereinsId);
  const finalId = `slot_${booking.date}_${booking.time.replace(':', '-')}_${booking.court.replace(/\s+/g, '_')}`;
  const docRef = doc(db, 'vereine', normalizedId, 'bookings', finalId);
  const cleanBooking = deepCleanUndefined(booking);

  try {
    await runTransaction(db, async (transaction) => {
      const docSnap = await transaction.get(docRef);
      if (docSnap.exists()) {
        const existingData = docSnap.data() as Booking;
        if (booking.id !== finalId && booking.id !== existingData.id) {
          throw new Error(`Besetzt: Der Zeitslot am ${booking.date} um ${booking.time} Uhr auf ${booking.court} ist bereits von einem anderen Mitglied gebucht oder gesperrt.`);
        }
      }
      transaction.set(docRef, { ...cleanBooking, id: finalId });
    });
  } catch (error) {
    handleFirestoreError(error, OperationType.WRITE, `vereine/${normalizedId}/bookings/${finalId}`);
  }
}

