export interface SystemUpdates {
  text: string;
  lastUpdated?: string;
  updatedBy?: string;
}

export function listenToSystemUpdates(callback: (updates: SystemUpdates | null) => void) {
  const path = 'system/updates';
  return onSnapshot(
    doc(db, 'system', 'updates'),
    (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        callback({
          text: data.text || "",
          lastUpdated: data.lastUpdated,
          updatedBy: data.updatedBy
        });
      } else {
        callback({ text: "" });
      }
    },
    (error) => {
      handleFirestoreError(error, OperationType.GET, path, false);
    }
  );
}

