// --- Backup & Rollback core functions (GLOBAL SYSTEM BACKUPS) ---

export function getWeekNumber(d: Date) {
  const date = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  date.setUTCDate(date.getUTCDate() + 4 - (date.getUTCDay() || 7));
  const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
  const weekNo = Math.ceil((((date.getTime() - yearStart.getTime()) / 86400000) + 1) / 7);
  return { year: date.getUTCFullYear(), week: weekNo };
}

export function getLastCompletedSunday(currentDate: Date): Date {
  const d = new Date(currentDate.getTime());
  const dayOfWeek = d.getDay(); // 0 (Sunday) to 6 (Saturday)
  // If today is Sunday (0), the last fully completed Sunday was 7 days ago.
  // Otherwise, subtract the current day of the week to get the last Sunday (yesterday or earlier).
  const daysToSubtract = dayOfWeek === 0 ? 7 : dayOfWeek;
  const lastSunday = new Date(d.getTime() - daysToSubtract * 24 * 60 * 60 * 1000);
  lastSunday.setHours(23, 59, 59, 999);
  return lastSunday;
}

export interface GlobalSystemBackup {
  id: string;
  timestamp: string;
  creator: "system" | "super-admin" | "rollback-auto" | "league-reset";
  name: string;
  clubs: any[];
  users: any[];
  memberships: any[];
  leagueMatches: any[];
  leagueProfiles: any[];
  leagueSearches?: any[];
  leagueConfigVersions?: any[];
  systemUpdates?: any;
  stats: {
    clubsCount: number;
    usersCount: number;
    membershipsCount: number;
    bookingsCount: number;
    tournamentsCount: number;
    matchesCount: number;
  };
}

export async function createGlobalBackup(
  creator: "system" | "super-admin" | "rollback-auto" | "league-reset",
  customId?: string,
  customName?: string
): Promise<GlobalSystemBackup> {
  const timestamp = new Date().toISOString();

  // 1. Fetch all clubs and their nested subcollections
  const clubsSnap = await getDocs(collection(db, 'vereine'));
  const clubsData: any[] = [];
  let totalBookings = 0;
  let totalTournaments = 0;

  for (const clubDoc of clubsSnap.docs) {
    const clubId = clubDoc.id;
    const clubData = clubDoc.data();

    // bookings
    const bookingsSnap = await getDocs(collection(db, 'vereine', clubId, 'bookings'));
    const bookings = bookingsSnap.docs.map(d => ({ id: d.id, ...d.data() }));
    totalBookings += bookings.length;

    // tournaments
    const tournamentsSnap = await getDocs(collection(db, 'vereine', clubId, 'tournaments'));
    const tournaments = tournamentsSnap.docs.map(d => ({ id: d.id, ...d.data() }));
    totalTournaments += tournaments.length;

    // arbeitseinsaetze
    const arbSnap = await getDocs(collection(db, 'vereine', clubId, 'arbeitseinsaetze'));
    const arbeitseinsaetze = arbSnap.docs.map(d => ({ id: d.id, ...d.data() }));

    // plannedWorkShifts
    const shiftsSnap = await getDocs(collection(db, 'vereine', clubId, 'plannedWorkShifts'));
    const plannedWorkShifts = shiftsSnap.docs.map(d => ({ id: d.id, ...d.data() }));

    // state
    const stateSnap = await getDocs(collection(db, 'vereine', clubId, 'state'));
    const states = stateSnap.docs.map(d => ({ id: d.id, data: d.data() }));

    clubsData.push({
      id: clubId,
      data: clubData,
      bookings,
      tournaments,
      arbeitseinsaetze,
      plannedWorkShifts,
      states,
    });
  }

  // 2. Fetch all users from global flat collection
  const usersSnap = await getDocs(collection(db, 'users'));
  const users = usersSnap.docs.map(d => ({ id: d.id, ...d.data() }));

  // 3. Fetch all memberships
  const membershipsSnap = await getDocs(collection(db, 'memberships'));
  const memberships = membershipsSnap.docs.map(d => ({ id: d.id, ...d.data() }));

  // 4. Fetch all league matches
  const matchesSnap = await getDocs(collection(db, 'league_matches'));
  const leagueMatches = matchesSnap.docs.map(d => ({ id: d.id, ...d.data() }));

  // 5. Fetch all league profiles
  const profilesSnap = await getDocs(collection(db, 'league_profiles'));
  const leagueProfiles = profilesSnap.docs.map(d => ({ id: d.id, ...d.data() }));

  // 6. Fetch league searches
  const searchesSnap = await getDocs(collection(db, 'league_searches'));
  const leagueSearches = searchesSnap.docs.map(d => ({ id: d.id, ...d.data() }));

  // 7. Fetch league config versions
  const configVersionsSnap = await getDocs(collection(db, 'league_config_versions'));
  const leagueConfigVersions = configVersionsSnap.docs.map(d => ({ id: d.id, ...d.data() }));

  // 8. Fetch system updates
  let systemUpdates: any = null;
  try {
    const sysUpdatesDoc = await getDoc(doc(db, 'system', 'updates'));
    if (sysUpdatesDoc.exists()) {
      systemUpdates = sysUpdatesDoc.data();
    }
  } catch (e) {
    console.warn("Could not read system/updates during backup:", e);
  }

  let id = customId;
  let backupName = customName || "";

  if (!backupName) {
    if (!id) {
      if (creator === "system") {
        const lastSunday = getLastCompletedSunday(new Date());
        const weekNum = getWeekNumber(lastSunday);
        id = `weekly_${weekNum.year}_W${weekNum.week}`;
        const sundayStr = lastSunday.toLocaleDateString("de-DE", { day: '2-digit', month: '2-digit', year: 'numeric' });
        backupName = `Wöchentliches System-Backup (KW ${weekNum.week} - Stand Sonntag, ${sundayStr})`;
      } else if (creator === "rollback-auto") {
        id = `rollback_auto_${Date.now()}`;
        backupName = `Automatisches Backup vor Rollback (${new Date(timestamp).toLocaleString("de-DE", { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' })})`;
      } else if (creator === "league-reset") {
        id = `league_reset_auto_${Date.now()}`;
        backupName = `Sicherheits-Snapshot vor Testdaten-Reset (${new Date(timestamp).toLocaleString("de-DE", { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' })})`;
      } else {
        id = `manual_${Date.now()}`;
        backupName = `Manuelles System-Backup (${new Date(timestamp).toLocaleString("de-DE", { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' })})`;
      }
    } else if (creator === "system") {
      const lastSunday = getLastCompletedSunday(new Date());
      const weekNum = getWeekNumber(lastSunday);
      const sundayStr = lastSunday.toLocaleDateString("de-DE", { day: '2-digit', month: '2-digit', year: 'numeric' });
      backupName = `Wöchentliches System-Backup (KW ${weekNum.week} - Stand Sonntag, ${sundayStr})`;
    } else if (creator === "rollback-auto") {
      backupName = `Automatisches Backup vor Rollback (${new Date(timestamp).toLocaleString("de-DE", { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' })})`;
    } else if (creator === "league-reset") {
      backupName = `Sicherheits-Snapshot vor Testdaten-Reset (${new Date(timestamp).toLocaleString("de-DE", { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' })})`;
    } else {
      backupName = `Manuelles System-Backup (${new Date(timestamp).toLocaleString("de-DE", { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' })})`;
    }
  }

  const finalId = id || `manual_${Date.now()}`;

  const backupData: GlobalSystemBackup = {
    id: finalId,
    timestamp,
    creator,
    name: backupName,
    clubs: clubsData,
    users,
    memberships,
    leagueMatches,
    leagueProfiles,
    leagueSearches,
    leagueConfigVersions,
    systemUpdates,
    stats: {
      clubsCount: clubsData.length,
      usersCount: users.length,
      membershipsCount: memberships.length,
      bookingsCount: totalBookings,
      tournamentsCount: totalTournaments,
      matchesCount: leagueMatches.length,
    }
  };

  const cleanedBackupData = deepCleanUndefined(backupData);
  await setDoc(doc(db, 'system_backups', finalId), cleanedBackupData);
  return backupData;
}

export async function restoreGlobalBackup(backupId: string) {
  let backupDoc = await getDoc(doc(db, 'system_backups', backupId));
  if (!backupDoc.exists()) {
    // Fallback to check root 'backups' collection if migrated
    backupDoc = await getDoc(doc(db, 'backups', backupId));
  }
  if (!backupDoc.exists()) {
    throw new Error("Das ausgewählte System-Backup existiert nicht mehr.");
  }

  const backup = backupDoc.data() as GlobalSystemBackup;

  // 1. Restore all clubs and their subcollections
  const currentClubsSnap = await getDocs(collection(db, 'vereine'));
  const backupClubIds = new Set((backup.clubs || []).map(c => c.id || c.vereinsId));

  // Clean subcollections of current clubs & remove deleted clubs
  for (const currentClubDoc of currentClubsSnap.docs) {
    const clubId = currentClubDoc.id;
    const subcollections = ['bookings', 'tournaments', 'arbeitseinsaetze', 'plannedWorkShifts', 'state', 'mitglieder'];
    for (const sub of subcollections) {
      try {
        const subSnap = await getDocs(collection(db, 'vereine', clubId, sub));
        for (const docItem of subSnap.docs) {
          await deleteDoc(doc(db, 'vereine', clubId, sub, docItem.id));
        }
      } catch (e) {}
    }

    if (!backupClubIds.has(clubId)) {
      try {
        await deleteDoc(doc(db, 'vereine', clubId));
      } catch (e) {}
    }
  }

  // Restore clubs from snapshot
  for (const club of (backup.clubs || [])) {
    const clubId = club.id || club.vereinsId;
    if (club.data) {
      await setDoc(doc(db, 'vereine', clubId), deepCleanUndefined(club.data));
    }

    if (club.bookings && Array.isArray(club.bookings)) {
      for (const b of club.bookings) {
        const bId = b.id || `slot_${b.date}_${(b.time || '').replace(':', '-')}_${(b.court || '').replace(/\s+/g, '_')}`;
        await setDoc(doc(db, 'vereine', clubId, 'bookings', bId), deepCleanUndefined(b));
      }
    }

    if (club.tournaments && Array.isArray(club.tournaments)) {
      for (const t of club.tournaments) {
        if (t.id) {
          await setDoc(doc(db, 'vereine', clubId, 'tournaments', t.id), deepCleanUndefined(t));
        }
      }
    }

    if (club.arbeitseinsaetze && Array.isArray(club.arbeitseinsaetze)) {
      for (const a of club.arbeitseinsaetze) {
        if (a.id) {
          await setDoc(doc(db, 'vereine', clubId, 'arbeitseinsaetze', a.id), deepCleanUndefined(a));
        }
      }
    }

    if (club.plannedWorkShifts && Array.isArray(club.plannedWorkShifts)) {
      for (const p of club.plannedWorkShifts) {
        if (p.id) {
          await setDoc(doc(db, 'vereine', clubId, 'plannedWorkShifts', p.id), deepCleanUndefined(p));
        }
      }
    }

    if (club.states && Array.isArray(club.states)) {
      for (const s of club.states) {
        if (s.id && s.data) {
          await setDoc(doc(db, 'vereine', clubId, 'state', s.id), deepCleanUndefined(s.data));
        }
      }
    }
  }

  // 2. Clean & restore Users
  const currentUsersSnap = await getDocs(collection(db, 'users'));
  for (const uDoc of currentUsersSnap.docs) {
    await deleteDoc(doc(db, 'users', uDoc.id));
  }
  for (const u of (backup.users || [])) {
    const docId = u.id || u.username;
    if (docId) {
      await setDoc(doc(db, 'users', docId), deepCleanUndefined(u));
    }
  }

  // 3. Clean & restore Memberships
  const currentMembershipsSnap = await getDocs(collection(db, 'memberships'));
  for (const mDoc of currentMembershipsSnap.docs) {
    await deleteDoc(doc(db, 'memberships', mDoc.id));
  }
  for (const m of (backup.memberships || [])) {
    if (m.id) {
      await setDoc(doc(db, 'memberships', m.id), deepCleanUndefined(m));
    }
  }

  // 4. Clean & restore League Matches
  const currentMatchesSnap = await getDocs(collection(db, 'league_matches'));
  for (const matchDoc of currentMatchesSnap.docs) {
    await deleteDoc(doc(db, 'league_matches', matchDoc.id));
  }
  for (const match of (backup.leagueMatches || [])) {
    if (match.id) {
      await setDoc(doc(db, 'league_matches', match.id), deepCleanUndefined(match));
    }
  }

  // 5. Clean & restore League Profiles
  const currentProfilesSnap = await getDocs(collection(db, 'league_profiles'));
  for (const profDoc of currentProfilesSnap.docs) {
    await deleteDoc(doc(db, 'league_profiles', profDoc.id));
  }
  for (const prof of (backup.leagueProfiles || [])) {
    if (prof.id) {
      await setDoc(doc(db, 'league_profiles', prof.id), deepCleanUndefined(prof));
    }
  }

  // 6. Clean & restore League Searches
  if (backup.leagueSearches && Array.isArray(backup.leagueSearches)) {
    const currentSearchesSnap = await getDocs(collection(db, 'league_searches'));
    for (const sDoc of currentSearchesSnap.docs) {
      await deleteDoc(doc(db, 'league_searches', sDoc.id));
    }
    for (const s of backup.leagueSearches) {
      if (s.id) {
        await setDoc(doc(db, 'league_searches', s.id), deepCleanUndefined(s));
      }
    }
  }

  // 7. Clean & restore League Config Versions
  if (backup.leagueConfigVersions && Array.isArray(backup.leagueConfigVersions)) {
    const currentConfigSnap = await getDocs(collection(db, 'league_config_versions'));
    for (const cDoc of currentConfigSnap.docs) {
      await deleteDoc(doc(db, 'league_config_versions', cDoc.id));
    }
    for (const cfg of backup.leagueConfigVersions) {
      if (cfg.id) {
        await setDoc(doc(db, 'league_config_versions', cfg.id), deepCleanUndefined(cfg));
      }
    }
  }

  // 8. Restore System Updates
  if (backup.systemUpdates) {
    await setDoc(doc(db, 'system', 'updates'), deepCleanUndefined(backup.systemUpdates));
  }
}

export async function cleanupOldGlobalBackups() {
  const backupsSnap = await getDocs(collection(db, 'system_backups'));
  const now = Date.now();
  const fourWeeksInMs = 4 * 7 * 24 * 60 * 60 * 1000;

  for (const d of backupsSnap.docs) {
    const backup = d.data();
    if (backup.creator === "system") {
      const age = now - new Date(backup.timestamp).getTime();
      if (age > fourWeeksInMs) {
        await deleteDoc(doc(db, 'system_backups', d.id));
      }
    }
  }
}

export function listenToGlobalBackups(callback: (backups: GlobalSystemBackup[]) => void) {
  const path = 'system_backups';
  return onSnapshot(
    collection(db, 'system_backups'),
    (snapshot) => {
      const data = snapshot.docs.map(d => ({ id: d.id, ...d.data() } as GlobalSystemBackup));
      data.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
      callback(data);
    },
    (error) => {
      handleFirestoreError(error, OperationType.LIST, path, false);
    }
  );
}

export async function checkAndPerformGlobalWeeklyBackup() {
  try {
    const lastSunday = getLastCompletedSunday(new Date());
    const weekNum = getWeekNumber(lastSunday);
    const weekId = `weekly_${weekNum.year}_W${weekNum.week}`;
    const cacheKey = `backup_checked_${weekId}`;

    // Skip if already successfully checked or created in this browser session/week
    const lastChecked = localStorage.getItem(cacheKey);
    if (lastChecked) {
      const hoursSinceCheck = (Date.now() - parseInt(lastChecked, 10)) / (1000 * 60 * 60);
      if (hoursSinceCheck < 24) {
        return;
      }
    }

    const backupDoc = await getDoc(doc(db, 'system_backups', weekId));
    if (!backupDoc.exists()) {
      console.log(`[Auto-Backup] Creating global weekly backup ${weekId}...`);
      await createGlobalBackup("system", weekId);
      await cleanupOldGlobalBackups();
    }
    localStorage.setItem(cacheKey, Date.now().toString());
  } catch (err) {
    console.warn("[Auto-Backup] Weekly backup check skipped or deferred:", err);
  }
}

