export function listenToArbeitseinsaetze(vereinsId: string, callback: (entries: ArbeitsEinsatz[]) => void) {
  const normalizedId = getNormalizedVereinsId(vereinsId);
  const path = `vereine/${normalizedId}/arbeitseinsaetze`;
  
  let unsub: (() => void) | undefined;
  let cancelled = false;

  waitForAuth.then(() => {
    if (cancelled || !auth.currentUser) return;
    unsub = onSnapshot(
      collection(db, 'vereine', normalizedId, 'arbeitseinsaetze'),
      (snapshot) => {
        const data = snapshot.docs.map(d => d.data() as ArbeitsEinsatz);
        callback(data);
      },
      (error) => {
        handleFirestoreError(error, OperationType.LIST, path, false);
      }
    );
  });

  return () => {
    cancelled = true;
    if (unsub) unsub();
  };
}

