export function listenToMemberships(vereinId: string, callback: (ms: Mitgliedschaft[]) => void) {
  const normalizedId = getNormalizedVereinsId(vereinId);
  const path = `vereine/${normalizedId}/mitglieder`;
  const q = collection(db, 'vereine', normalizedId, 'mitglieder');
  return onSnapshot(q, (snapshot) => {
    const list: Mitgliedschaft[] = snapshot.docs.map(d => {
      const data = d.data();
      return {
        id: d.id,
        personId: data.personId || d.id,
        vereinId: data.vereinId || normalizedId,
        role: data.role || Role.MITGLIED,
        active: data.active !== false,
        createdAt: data.createdAt || new Date().toISOString()
      };
    });
    callback(list);
  }, (err) => {
    handleFirestoreError(err, OperationType.LIST, path, false);
  });
}

export async function saveMembership(vereinId: string, membership: Mitgliedschaft) {
  const normalizedId = getNormalizedVereinsId(vereinId);
  const docId = membership.id || `${membership.personId}_${normalizedId}`;
  const path = `vereine/${normalizedId}/mitglieder/${docId}`;
  try {
    await setDoc(doc(db, 'vereine', normalizedId, 'mitglieder', docId), {
      ...membership,
      id: docId,
      vereinId: normalizedId,
      active: membership.active !== false
    }, { merge: true });
  } catch (error) {
    handleFirestoreError(error, OperationType.WRITE, path);
  }
}

export async function deleteMembership(vereinId: string, membershipId: string) {
  const normalizedId = getNormalizedVereinsId(vereinId);
  const path = `vereine/${normalizedId}/mitglieder/${membershipId}`;
  try {
    await deleteDoc(doc(db, 'vereine', normalizedId, 'mitglieder', membershipId));
  } catch (error) {
    handleFirestoreError(error, OperationType.DELETE, path);
  }
}





